RE id = (SELECT atendimento_id FROM upd_relatorio)\n    AND $5::status_presenca IS NOT NULL\n  RETURNING id, status_presenca::text AS status_presenca\n)\nSELECT\n  (SELECT id FROM upd_relatorio) IS NOT NULL AS encontrado,\n  (SELECT id FROM upd_relatorio) AS id,\n  (SELECT tipo FROM upd_relatorio) AS tipo,\n  (SELECT paciente_id FROM upd_relatorio) AS paciente_id,\n  (SELECT autor_id FROM upd_relatorio) AS autor_id,\n  (SELECT editado_por_id FROM upd_relatorio) AS editado_por_id,\n  (SELECT data FROM upd_relatorio) AS data,\n  (SELECT conteudo FROM upd_relatorio) AS conteudo,\n  (SELECT updated_at FROM upd_relatorio) AS updated_at,\n  (SELECT atendimento_id FROM upd_relatorio) AS atendimento_id,\n  (SELECT status_presenca FROM upd_atendimento) AS status_presenca","options":{"queryReplacement":"={{ [ $json.body.id, $json.body.data || null, $json.body.conteudo || null, $json.body.editado_por_nome, $json.body.status_presenca || null ] }}"}},"credentials":{"postgres":{"id":"eqtrPgCredential01","name":"Equitar Postgres"}}},{"id":"if_encontrado","name":"Encontrado?","type":"n8n-nodes-base.if","typeVersion":2.3,"position":[520,300],"parameters":{"conditions":{"combinator":"and","conditions":[{"leftValue":"={{ $json.encontrado }}","rightValue":true,"operator":{"type":"boolean","operation":"equals"}}],"options":{"caseSensitive":true,"typeValidation":"strict","version":2}}}},{"id":"respond_sucesso","name":"Responder Sucesso","type":"n8n-nodes-base.respondToWebhook","typeVersion":1.5,"position":[780,200],"parameters":{"respondWith":"json","responseBody":"={{ { sucesso: true, mensagem: \"Relatório atualizado com sucesso.\", relatorio: { id: $json.id, tipo: $json.tipo, pacienteId: $json.paciente_id, autorId: $json.autor_id, editadoPorId: $json.editado_por_id, data: $json.data, conteudo: $json.conteudo, atendimentoId: $json.atendimento_id, statusPresenca: $json.status_presenca } } }}","options":{"responseCode":200}}},{"id":"respond_nao_encontrado","name":"Responder Nao Encontrado